Dataspatium.assets.register("presets/api/lantmateriet-geodata.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"lantmateriet-geodata\",\n  \"name\": \"Lantmäteriet öppna geodata (katalog)\",\n  \"publisher\": \"Lantmäteriet\",\n  \"description\": \"Katalog (STAC) över Lantmäteriets öppna vektordata: ortnamn, administrativ indelning, topografi med mera, med nedladdningslänkar. Filerna laddas ned i webbläsaren och importeras sedan som filer.\",\n  \"docs\": \"https://www.lantmateriet.se/sv/geodata/vara-produkter/oppna-data/\",\n  \"license\": { \"name\": \"CC0 1.0\", \"url\": \"https://creativecommons.org/publicdomain/zero/1.0/\" },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://api.lantmateriet.se/stac-vektor/v1\",\n  \"auth\": { \"type\": \"none\" },\n  \"endpoints\": [\n    {\n      \"id\": \"collections\",\n      \"name\": \"Produkter (samlingar)\",\n      \"method\": \"GET\",\n      \"path\": \"/collections\",\n      \"response\": { \"format\": \"json\", \"path\": \"collections\", \"drop\": [\"links\", \"stac_version\", \"stac_extensions\", \"type\"], \"rename\": { \"id\": \"produkt\", \"title\": \"titel\", \"description\": \"beskrivning\", \"license\": \"licens\" } },\n      \"dataset\": { \"name\": \"Lantmäteriet produkter\" }\n    },\n    {\n      \"id\": \"items\",\n      \"name\": \"Filer i en produkt\",\n      \"method\": \"GET\",\n      \"path\": \"/collections/{collection}/items\",\n      \"params\": [\n        { \"name\": \"collection\", \"in\": \"path\", \"label\": \"Produkt\", \"type\": \"string\", \"required\": true, \"optionsFrom\": { \"endpoint\": \"collections\", \"value\": \"produkt\", \"label\": \"titel\" } },\n        { \"name\": \"limit\", \"in\": \"query\", \"type\": \"number\", \"default\": 100, \"hidden\": true }\n      ],\n      \"pagination\": { \"type\": \"link-rel\", \"path\": \"links\", \"rel\": \"next\", \"maxPages\": 20 },\n      \"response\": { \"format\": \"geojson\", \"options\": { \"geometry\": false }, \"drop\": [\"links\", \"stac_version\", \"stac_extensions\", \"collection\", \"type\"] },\n      \"dataset\": { \"name\": \"Lantmäteriet {collection} filer\" }\n    }\n  ],\n  \"i18n\": {\n    \"en\": {\"name\": \"Lantmäteriet open geodata (catalogue)\", \"description\": \"Catalogue (STAC) of Lantmäteriet's open vector data for Sweden: place names, administrative divisions, topography and more, with download links. The files are downloaded in the browser and then imported as files.\", \"endpoints\": {\"collections\": {\"name\": \"Products (collections)\"}, \"items\": {\"name\": \"Files in a product\", \"params\": {\"collection\": {\"label\": \"Product\"}}}}, \"dataset\": {\"collections\": \"Lantmäteriet products\", \"items\": \"Lantmäteriet {collection} files\"}},\n    \"da\": {\"name\": \"Lantmäteriet åbne geodata (katalog)\", \"description\": \"Katalog (STAC) over Lantmäteriets åbne vektordata for Sverige: stednavne, administrativ inddeling, topografi med mere, med downloadlinks. Filerne downloades i browseren og importeres derefter som filer.\", \"endpoints\": {\"collections\": {\"name\": \"Produkter (samlinger)\"}, \"items\": {\"name\": \"Filer i et produkt\", \"params\": {\"collection\": {\"label\": \"Produkt\"}}}}, \"dataset\": {\"collections\": \"Lantmäteriet produkter\", \"items\": \"Lantmäteriet {collection} filer\"}},\n    \"nb\": {\"name\": \"Lantmäteriet åpne geodata (katalog)\", \"description\": \"Katalog (STAC) over Lantmäteriets åpne vektordata for Sverige: stedsnavn, administrativ inndeling, topografi med mer, med nedlastingslenker. Filene lastes ned i nettleseren og importeres deretter som filer.\", \"endpoints\": {\"collections\": {\"name\": \"Produkter (samlinger)\"}, \"items\": {\"name\": \"Filer i et produkt\", \"params\": {\"collection\": {\"label\": \"Produkt\"}}}}, \"dataset\": {\"collections\": \"Lantmäteriet produkter\", \"items\": \"Lantmäteriet {collection} filer\"}},\n    \"fi\": {\"name\": \"Lantmäteriet: avoin paikkatieto (luettelo)\", \"description\": \"Luettelo (STAC) Lantmäterietin avoimesta vektoridatasta Ruotsista: paikannimet, hallinnollinen jako, topografia ja muuta latauslinkkeineen. Tiedostot ladataan selaimessa ja tuodaan sitten tiedostoina.\", \"endpoints\": {\"collections\": {\"name\": \"Tuotteet (kokoelmat)\"}, \"items\": {\"name\": \"Tuotteen tiedostot\", \"params\": {\"collection\": {\"label\": \"Tuote\"}}}}, \"dataset\": {\"collections\": \"Lantmäteriet tuotteet\", \"items\": \"Lantmäteriet {collection} tiedostot\"}},\n    \"is\": {\"name\": \"Lantmäteriet: opin landupplýsingagögn (skrá)\", \"description\": \"Skrá (STAC) yfir opin vigurgögn Lantmäteriet fyrir Svíþjóð: örnefni, stjórnsýsluskiptingu, landslag og fleira, með niðurhalstenglum. Skrárnar eru sóttar í vafranum og síðan fluttar inn sem skrár.\", \"endpoints\": {\"collections\": {\"name\": \"Vörur (söfn)\"}, \"items\": {\"name\": \"Skrár í vöru\", \"params\": {\"collection\": {\"label\": \"Vara\"}}}}, \"dataset\": {\"collections\": \"Lantmäteriet vörur\", \"items\": \"Lantmäteriet {collection} skrár\"}}\n  }\n}\n");
